<script setup lang="ts">
/**
 * The Kinotic brand logo: the mark on its own, or the mark paired with the wordmark.
 * Decorative by default — give the surrounding link or button the accessible name.
 */
const props = withDefaults(defineProps<{
  variant?: 'lockup' | 'mark'
  height?: number
  markColor?: string
  wordColor?: string
}>(), {
  variant: 'lockup',
  height: 32,
  markColor: '#28FEB4',
  wordColor: '#EDEDEF',
})

// The wordmark's cap height sits below the mark's full bounding box, so it is set
// slightly shorter to make the two read as one baseline-aligned lockup.
const wordHeight = computed(() => props.height * 0.86)
const gap = computed(() => Math.round(props.height * 0.34))
</script>

